define_helper ! (#[doc = " Avoids running select queries during any prints that occur"] #[doc = " during the closure. This may alter the appearance of some"] #[doc = " types (e.g. forcing verbose printing for opaque types)."] #[doc = " This method is used during some queries (e.g. `explicit_item_bounds`"] #[doc = " for opaque types), to ensure that any debug printing that"] #[doc = " occurs during the query computation does not end up recursively"] #[doc = " calling the same query."] fn with_reduced_queries (ReducedQueriesGuard , REDUCED_QUERIES) ; #[doc = " Force us to name impls with just the filename/line number. We"] #[doc = " normally try to use types. But at some points, notably while printing"] #[doc = " cycle errors, this can result in extra or suboptimal error output,"] #[doc = " so this variable disables that check."] fn with_forced_impl_filename_line (ForcedImplGuard , FORCE_IMPL_FILENAME_LINE) ; #[doc = " Adds the crate name prefix to paths where appropriate."] #[doc = " Unlike `with_crate_prefix`, this unconditionally uses `tcx.crate_name` instead of sometimes"] #[doc = " using `crate::` for local items."] #[doc = ""] #[doc = " Overrides `with_crate_prefix`."] fn with_resolve_crate_name (CrateNamePrefixGuard , SHOULD_PREFIX_WITH_CRATE_NAME) ; #[doc = " Adds the `crate::` prefix to paths where appropriate."] #[doc = ""] #[doc = " Ignored if `with_resolve_crate_name` is active."] fn with_crate_prefix (CratePrefixGuard , SHOULD_PREFIX_WITH_CRATE) ; #[doc = " Prevent path trimming if it is turned on. Path trimming affects `Display` impl"] #[doc = " of various rustc types, for example `std::vec::Vec` would be trimmed to `Vec`,"] #[doc = " if no other `Vec` is found."] fn with_no_trimmed_paths (NoTrimmedGuard , NO_TRIMMED_PATH) ; fn with_forced_trimmed_paths (ForceTrimmedGuard , FORCE_TRIMMED_PATH) ; #[doc = " Prevent selection of visible paths. `Display` impl of DefId will prefer"] #[doc = " visible (public) reexports of types as paths."] fn with_no_visible_paths (NoVisibleGuard , NO_VISIBLE_PATH) ; #[doc = " Prevent selection of visible paths if the paths are through a doc hidden path."] fn with_no_visible_paths_if_doc_hidden (NoVisibleIfDocHiddenGuard , NO_VISIBLE_PATH_IF_DOC_HIDDEN) ;) ;